def solve(
    a: float,
) -> tuple[list[float], list[float]]:
    return fold_points(a)

def fold_points(a):
    state=math.sqrt(a/3)
    positions=[-state,state]
    return positions,[x**3-a*x for x in positions]

p04-bias-continuation:
import math

def solve(
    biases: list[float],
    initial: float,
    h: float,
    steps: int,
    carry: bool,
) -> list[float]:
    return scan_bias(biases,initial,h,steps,carry)

def switch_step(state,bias,h):
    first=state-state**3+bias
    middle=state+h*first/2
    return state+h*(middle-middle**3+bias)

def scan_bias(biases,initial,h,steps,carry):
    final=[]
    state=initial
    for bias in biases:
        if not carry:state=initial
        for _ in range(steps):state=switch_step(state,bias,h)
        final.append(state)
    return final

