p04-prediction-horizon:
import math

def solve(
    r: float,
    first: float,
    second: float,
    threshold: float,
    steps: int,
) -> tuple[list[float], int | None]:
    return separation(r,first,second,threshold,steps)

def logistic_path(r,initial,steps):
    values=[initial]
    for _ in range(steps):values.append(r*values[-1]*(1-values[-1]))
    return values

def separation(r,first,second,threshold,steps):
    a=logistic_path(r,first,steps)
    b=logistic_path(r,second,steps)
    distances=[abs(x-y) for x,y in zip(a,b)]
    crossing=next((i for i,d in enumerate(distances) if d>threshold),None)
    return distances,crossing

p04-finite-growth:
import math

def solve(
    r: float,
    initial: float,
    burn: int,
    steps: int,
) -> float | None:
    return finite_growth(r,initial,burn,steps)

def finite_growth(r,initial,burn,steps):
    state=initial
    for _ in range(burn):state=r*state*(1-state)
    logs=[]
    for _ in range(steps):
        derivative=abs(r*(1-2*state))
        if derivative==0:return None
        logs.append(math.log(derivative))
        state=r*state*(1-state)
    return sum(logs)/steps

