import math

def solve(
    points: list[float],
) -> tuple[list[float], list[float], list[bool]]:
    return local_energy(points)

def local_energy(points):
    values=[x*x/2 for x in points]
    derivatives=[-x*x+x**4 for x in points]
    strict=[0<abs(x)<1 for x in points]
    return values,derivatives,strict

p04-rotating-energy:
import math

def solve(
    points: list[list[float]],
    alpha: float,
    omega: float,
) -> tuple[list[float], list[float]]:
    return quadratic_energy(points,alpha,omega)

def quadratic_energy(points,alpha,omega):
    values=[];derivatives=[]
    for x,y in points:
        values.append((x*x+y*y)/2)
        rate=[-alpha*x-omega*y,omega*x-alpha*y]
        derivatives.append(x*rate[0]+y*rate[1])
    return values,derivatives

