p04-directed-section:
import math

def solve(
    times: list[float],
    states: list[list[float]],
    level: float,
    burn: float,
) -> tuple[list[list[float]], list[float]]:
    hits=[]
    for i in range(len(times)-1):
        a,b=states[i],states[i+1]
        if a[2]<level<=b[2]:
            fraction=(level-a[2])/(b[2]-a[2])
            t=times[i]+fraction*(times[i+1]-times[i])
            if t>=burn:
                hits.append([t]+[a[j]+fraction*(b[j]-a[j]) for j in range(3)])
    return hits,[hits[i+1][0]-hits[i][0] for i in range(len(hits)-1)]

