import math

def solve(
    rates: list[float],
    initial_delta: list[float],
    time: float,
) -> tuple[list[float], float]:
    delta=[v*math.exp(r*time) for r,v in zip(rates,initial_delta)]
    norm=lambda v:math.sqrt(sum(x*x for x in v))
    return delta,norm(delta)/norm(initial_delta)

