p04-cap-precision:
import math

def solve(
    map_derivatives: list[float],
    stretch_factors: list[float],
    durations: list[float],
) -> tuple[float | None, float]:
    discrete=None if 0 in map_derivatives else math.fsum(math.log(abs(d)) for d in map_derivatives)/len(map_derivatives)
